CREATE COLUMN TABLE "TEST_AP"."OBCD" ("BcdEntry" INTEGER CS_INT NOT NULL , "BcdCode" NVARCHAR(254) NOT NULL , "BcdName" NVARCHAR(100), "ItemCode" NVARCHAR(50) NOT NULL , "UomEntry" INTEGER CS_INT NOT NULL , "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "LogInstanc" INTEGER CS_INT DEFAULT 0, "UserSign2" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, "CreateDate" LONGDATE CS_LONGDATE, PRIMARY KEY ("BcdEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OBCD_ITEM" ON "TEST_AP"."OBCD" ( "ItemCode" ASC, "UomEntry" ASC, "BcdCode" ASC );
CREATE INDEX "OBCD_BCD_CODE" ON "TEST_AP"."OBCD" ( "BcdCode" ASC )